  condition: "selector_visible",
  value: 'a[href*="/cat/"]',
  timeout_ms: 15000
});
console.log("Wait res:", waitRes);

// Now extract the cats
const cards = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/cat/"]'));
  const results = [];
  const seen = new Set();
  for (const a of links) {
    if (seen.has(a.href)) continue;
    seen.add(a.href);

    // Find enclosing card
    let p = a;
    for (let i = 0; i < 5; i++) {
      if (p && (p.innerText?.includes('miles away') || p.innerText?.includes('Young'))) break;
      if (p) p = p.parentElement;
    }
    results.push({
      href: a.href,
      text: p?.innerText?.split('\n').map(s => s.trim()).filter(Boolean) || []
    });
  }
  return results;
});

console.log(`Extracted ${cards.length} cards.`);
for (let i = 0; i < cards.length; i++) {
  console.log(`#${i + 1}: ${cards[i].text.slice(0, 5).join(' | ')} (${cards[i].href})`);
}

await write("tmp://cards.json", JSON.stringify(cards, null, 2), "application/json");

