const tabId = 730410078;
const details = await browserjs(tabId, () => {
  // Let's find all pet cards on the page
  // Petfinder usually has card containers around pet links
  const links = Array.from(document.querySelectorAll('a[href*="/cat/"]'));
  // Find distinct cards
  const cards = [];
  const seenUrls = new Set();
  for (const link of links) {
    if (seenUrls.has(link.href)) continue;
    seenUrls.add(link.href);

    // Find enclosing card
    let parent = link;
    while (parent && parent !== document.body && !parent.querySelector('img') && !parent.innerText?.includes('miles away') && !parent.innerText?.includes('Young')) {
      parent = parent.parentElement;
    }
    // Alternatively look for common card class
    let cardEl = link.closest('[data-testid*="pet-card"]') || 
                 link.closest('[class*="petCard"]') || 
                 link.closest('[class*="PetCard"]') ||
                 link.closest('article') ||
                 link.closest('div[class*="card"]');
    if (!cardEl) {
      // Traverse up to find element with text content
      let curr = link.parentElement;
      for (let i = 0; i < 5; i++) {
        if (curr && (curr.innerText?.includes('Young') || curr.innerText?.includes('miles'))) {
          cardEl = curr;
          break;
        }
        if (curr) curr = curr.parentElement;
      }
    }

    cards.push({
      href: link.href,
      cardText: (cardEl ? cardEl.innerText : link.parentElement?.innerText || '').split('\n').map(s => s.trim()).filter(Boolean),
      img: cardEl?.querySelector('img')?.src || link.querySelector('img')?.src || ''
    });
  }
  return cards;
});

console.log(`Extracted ${details.length} cards.`);
for (let i = 0; i < details.length; i++) {
  console.log(`\n=== Card ${i + 1} ===`);
  console.log("Href:", details[i].href);
  console.log("Text:", details[i].cardText);
  console.log("Img:", details[i].img);
}

